import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.*;

/**
 * Unit tests for DeserializationConfig#getDefaultVisibilityChecker
 */
public class DeserializationConfig_getDefaultVisibilityChecker_TriageGen1Test {

    private BaseSettings baseSettings;
    private SubtypeResolver subtypeResolver;
    private SimpleMixInResolver mixins;
    private RootNameLookup rootNames;
    private DeserializationConfig config;

    @Before
    public void setUp() {
        // Mocking dependencies required for DeserializationConfig constructor
        baseSettings = mock(BaseSettings.class);
        subtypeResolver = mock(SubtypeResolver.class);
        mixins = mock(SimpleMixInResolver.class);
        rootNames = mock(RootNameLookup.class);

        // We use a spy or a real instance. Since DeserializationConfig is part of Jackson,
        // we'll instantiate it. Note: In a real Jackson environment, we'd use ObjectMapper,
        // but here we follow the provided constructor.
        config = new DeserializationConfig(baseSettings, subtypeResolver, mixins, rootNames);
    }

    @Test
    public void testGetDefaultVisibilityChecker_AllFeaturesEnabled() {
        // When all AUTO_DETECT features are enabled, the visibility checker should remain unchanged from super
        // We simulate this by ensuring isEnabled returns true for the relevant MapperFeatures
        DeserializationConfig configWithAll = config.with(
                MapperFeature.AUTO_DETECT_SETTERS,
                MapperFeature.AUTO_DETECT_CREATORS,
                MapperFeature.AUTO_DETECT_FIELDS
        );

        VisibilityChecker<?> checker = configWithAll.getDefaultVisibilityChecker();

        // Verification: Since we can't easily check the "super" state without complex mocking, 
        // we verify that the visibility is NOT NONE (assuming default is something else like ANY or PUBLIC)
        // In Jackson, default is usually AUTO.
        assertEquals(Visibility.ANY, checker.getGetterVisibility());
        assertEquals(Visibility.ANY, checker.getSetterVisibility());
        assertEquals(Visibility.ANY, checker.getFieldVisibility());
        assertEquals(Visibility.ANY, checker.getCreatorVisibility());
    }

    @Test
    public void testGetDefaultVisibilityChecker_DisableSetters() {
        // Disable only AUTO_DETECT_SETTERS
        DeserializationConfig configWithNoSetters = config.without(MapperFeature.AUTO_DETECT_SETTERS);

        VisibilityChecker<?> checker = configWithNoSetters.getDefaultVisibilityChecker();

        assertEquals(Visibility.NONE, checker.getSetterVisibility());
        // Others should remain default (ANY)
        assertEquals(Visibility.ANY, checker.getFieldVisibility());
        assertEquals(Visibility.ANY, checker.getCreatorVisibility());
    }

    @Test
    public void testGetDefaultVisibilityChecker_DisableCreators() {
        // Disable only AUTO_DETECT_CREATORS
        DeserializationConfig configWithNoCreators = config.without(MapperFeature.AUTO_DETECT_CREATORS);

        VisibilityChecker<?> checker = configWithNoCreators.getDefaultVisibilityChecker();

        assertEquals(Visibility.NONE, checker.getCreatorVisibility());
        // Others should remain default
        assertEquals(Visibility.ANY, checker.getSetterVisibility());
        assertEquals(Visibility.ANY, checker.getFieldVisibility());
    }

    @Test
    public void testGetDefaultVisibilityChecker_DisableFields() {
        // Disable only AUTO_DETECT_FIELDS
        DeserializationConfig configWithNoFields = config.without(MapperFeature.AUTO_DETECT_FIELDS);

        VisibilityChecker<?> checker = configWithNoFields.getDefaultVisibilityChecker();

        assertEquals(Visibility.NONE, checker.getFieldVisibility());
        // Others should remain default
        assertEquals(Visibility.ANY, checker.getSetterVisibility());
        assertEquals(Visibility.ANY, checker.getCreatorVisibility());
    }

    @Test
    public void testGetDefaultVisibilityChecker_DisableAll() {
        // Disable all three features
        DeserializationConfig configWithNone = config.without(
                MapperFeature.AUTO_DETECT_SETTERS,
                MapperFeature.AUTO_DETECT_CREATORS,
                MapperFeature.AUTO_DETECT_FIELDS
        );

        VisibilityChecker<?> checker = configWithNone.getDefaultVisibilityChecker();

        assertEquals(Visibility.NONE, checker.getSetterVisibility());
        assertEquals(Visibility.NONE, checker.getCreatorVisibility());
        assertEquals(Visibility.NONE, checker.getFieldVisibility());
    }
}
